namespace CourseCatalog.Models;

public class Department
{
    public required string Id { get; init; }
    public required string Name { get; init; }
    public required string Description { get; init; }
}

namespace CourseCatalog.Models;

public class Course
{
    public required string Id { get; init; }
    public required string DepartmentId { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public required int Credits { get; init; }
    public required string Schedule { get; init; }
    public required string InstructorName { get; init; }
    public required string InstructorBio { get; init; }
    public bool IsFeatured { get; init; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20)]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = "";
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics including analysis, algebra, and statistics." },
        new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." },
        new() { Id = "hist", Name = "History", Description = "Exploration of past events, civilizations, and cultural developments." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = "CS101", DepartmentId = "cs", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace has over 15 years of experience teaching introductory programming. Her research focuses on CS education and accessible computing.", IsFeatured = true },
        new() { Id = "CS201", DepartmentId = "cs", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. Alan Turing", InstructorBio = "Dr. Turing specializes in algorithm analysis and computational complexity theory. He has published extensively in top-tier journals.", IsFeatured = true },
        new() { Id = "CS301", DepartmentId = "cs", Title = "Database Systems", Description = "Principles of database design, relational algebra, SQL, normalization, and transaction management.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Edgar Codd", InstructorBio = "Dr. Codd brings industry experience from major database vendors and focuses on modern database architectures." },
        new() { Id = "CS401", DepartmentId = "cs", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search, knowledge representation, machine learning, and natural language processing.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Grace Hopper", InstructorBio = "Dr. Hopper researches applied machine learning and has led several industry-academic collaboration projects.", IsFeatured = true },

        new() { Id = "MATH101", DepartmentId = "math", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Prof. Euclid", InstructorBio = "Prof. Euclid has taught calculus for over 20 years and has received multiple teaching awards.", IsFeatured = true },
        new() { Id = "MATH201", DepartmentId = "math", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is an expert in abstract algebra with a passion for making advanced math accessible." },
        new() { Id = "MATH301", DepartmentId = "math", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", InstructorName = "Dr. Carl Gauss", InstructorBio = "Dr. Gauss specializes in statistical modeling and data analysis methodologies." },

        new() { Id = "PHYS101", DepartmentId = "phys", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM, Lab: Thu 2:00–4:50 PM", InstructorName = "Dr. Isaac Newton", InstructorBio = "Dr. Newton is a renowned researcher in classical mechanics and an engaging lecturer." },
        new() { Id = "PHYS201", DepartmentId = "phys", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM, Lab: Fri 2:00–4:50 PM", InstructorName = "Dr. James Maxwell", InstructorBio = "Dr. Maxwell's research spans electromagnetic theory and photonics.", IsFeatured = true },

        new() { Id = "ENG101", DepartmentId = "eng", Title = "English Composition", Description = "Develop critical reading and academic writing skills. Focus on essay structure, argumentation, and revision.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Prof. Virginia Woolf", InstructorBio = "Prof. Woolf is an acclaimed writing instructor who emphasizes clarity and creative expression." },
        new() { Id = "ENG201", DepartmentId = "eng", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", InstructorName = "Dr. Mark Twain", InstructorBio = "Dr. Twain specializes in 19th-century American literature and humor studies." },

        new() { Id = "HIST101", DepartmentId = "hist", Title = "World History I", Description = "Survey of world civilizations from ancient times through the Renaissance.", Credits = 3, Schedule = "Mon/Wed/Fri 2:00–2:50 PM", InstructorName = "Dr. Herodotus", InstructorBio = "Dr. Herodotus has extensive fieldwork experience in archaeological history." },
        new() { Id = "HIST201", DepartmentId = "hist", Title = "Modern European History", Description = "Europe from the Enlightenment through the 20th century, including political, social, and cultural transformations.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", InstructorName = "Dr. Mary Shelley", InstructorBio = "Dr. Shelley focuses on European intellectual history and the history of science.", IsFeatured = true },
    ];

    public List<Department> GetDepartments() => Departments;

    public Department? GetDepartment(string id) =>
        Departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetAllCourses() => Courses;

    public List<Course> GetFeaturedCourses() =>
        Courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, string? departmentId)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Id.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(string id) =>
        Courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));
}

